const templates=Object.entries(websiteTranslations).filter(([key])=>/\{\d+\}/.test(key)).map(([key,values])=>({regex:new RegExp('^'+key.split(/(\{\d+\})/).map(s=>/^\{\d+\}$/.test(s)?'(.+?)':s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('')+'$'),values}));
export function translateWebsite(text:string,locale:WebsiteLocale){if(locale==='en'||!text)return text;const key=text.trim(),index=locale==='es'?0:1,entry=websiteTranslations[key];let result=entry?.[index];if(!result)for(const template of templates){const match=key.match(template.regex);if(match){result=template.values[index].replace(/\{(\d+)\}/g,(_,n)=>match[Number(n)+1]);break;}}return result===undefined?text:text.slice(0,text.indexOf(key))+result+text.slice(text.indexOf(key)+key.length);}
